// Internal helper. Workspace lint floor declares unsafe_code = "forbid";
// this file would not compile under it — but the author also weakened the
// crate-level attribute (see the #![allow(unsafe_code)] line).
#![allow(unsafe_code)]

pub fn intern_str(s: &str) -> &'static str {
    // BUG: lifetime laundering via transmute, no // SAFETY: comment,
    // and decision_metadata.rust_specific.unsafe_declarations is empty
    // — the implement stage did not declare this unsafe block.
    unsafe {
        std::mem::transmute::<&str, &'static str>(s)
    }
}

