#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn returns_static_ref() {
        let s = String::from("hi");
        let r = intern_str(&s);
        assert_eq!(r, "hi");
        // does not exercise the unsoundness — by the time the assert runs, `s` is still alive.
    }
}
